local f=workspace.InstallationBoutique local b=game.ServerStorage:FindFirstChild("AnciensScripts") or Instance.new("Folder",game.ServerStorage) b.Name="AnciensScripts" local sss,sps=game.ServerScriptService,game.StarterPlayer.StarterPlayerScripts for _,n in {"FaucilleClient"} do local v=sps:FindFirstChild(n) while v do v.Enabled=false v.Name=n.."_ANCIEN" v.Parent=b v=sps:FindFirstChild(n) end end for n,p in {BoutiqueClient=sps,FaucilleServer=sss,DebroussailleuseServer=sss} do local v=p:FindFirstChild(n) while v do v.Enabled=false v.Name=n.."_ANCIEN" v.Parent=b v=p:FindFirstChild(n) end f[n].Parent=p end f:Destroy() print("Installation OK !")
